import { useLayoutEffect, useMemo, useRef } from 'react'
import { useFrame } from '@react-three/fiber'
import * as THREE from 'three'
import { getGlow, GOLD, CREAM, ROSE_COLORS } from './GardenShared.js'

export function Roses() {
  const bushRef = useRef()
    const roseRef = useRef()
      const { bushes, roses } = useMemo(() => {
          const bushes = []
              const roses = []
                  const pick = () => ROSE_COLORS[Math.floor(Math.random() * ROSE_COLORS.length)]
                      for (let i = 0; i < 60; i++) {
                            const s = i % 2 ? 1 : -1
                                  const b = { x: s * (4.4 + Math.random() * 5.5), z: 7 - Math.random() * 32, s: 0.45 + Math.random() * 0.3 }
                                        bushes.push(b)
                                              for (let k = 0; k < 4; k++) {
                                                      const a = Math.random() * Math.PI * 2
                                                              roses.push({
                                                                        x: b.x + Math.cos(a) * b.s * 0.8,
                                                                                  y: 0.45 + Math.random() * 0.4,
                                                                                            z: b.z + Math.sin(a) * b.s * 0.8,
                                                                                                      s: 0.8 + Math.random() * 0.5,
                                                                                                                c: pick(),
                                                                                                                        })
                                                                                                                              }
                                                                                                                                  }
                                                                                                                                      for (const s of [-1, 1]) {
                                                                                                                                            for (let z = 6; z > -25; z -= 0.5) {
                                                                                                                                                    roses.push({ x: s * 2.78, y: 0.4 + Math.random() * 1.05, z: z + Math.random() * 0.3, s: 0.9 + Math.random() * 0.5, c: pick() })
                                                                                                                                                          }
                                                                                                                                                              }
                                                                                                                                                                  for (let i = 0; i <= 16; i++) {
                                                                                                                                                                        const a = (i / 16) * Math.PI
                                                                                                                                                                              roses.push({ x: 1.6 * Math.cos(a), y: 2.4 + 1.6 * Math.sin(a), z: -8, s: 1.1, c: pick() })
                                                                                                                                                                                  }
                                                                                                                                                                                      return { bushes, roses }
                                                                                                                                                                                        }, [])

                                                                                                                                                                                          useLayoutEffect(() => {
                                                                                                                                                                                              const d = new THREE.Object3D()
                                                                                                                                                                                                  const col = new THREE.Color()
                                                                                                                                                                                                      bushes.forEach((b, i) => {
                                                                                                                                                                                                            d.position.set(b.x, 0.35, b.z)
                                                                                                                                                                                                                  d.scale.set(b.s, b.s * 0.8, b.s)
                                                                                                                                                                                                                        d.updateMatrix()
                                                                                                                                                                                                                              bushRef.current.setMatrixAt(i, d.matrix)
                                                                                                                                                                                                                                  })
                                                                                                                                                                                                                                      bushRef.current.instanceMatrix.needsUpdate = true
                                                                                                                                                                                                                                          roses.forEach((r, i) => {
                                                                                                                                                                                                                                                d.position.set(r.x, r.y, r.z)
                                                                                                                                                                                                                                                      d.scale.setScalar(r.s)
                                                                                                                                                                                                                                                            d.updateMatrix()
                                                                                                                                                                                                                                                                  roseRef.current.setMatrixAt(i, d.matrix)
                                                                                                                                                                                                                                                                        roseRef.current.setColorAt(i, col.set(r.c))
                                                                                                                                                                                                                                                                            })
                                                                                                                                                                                                                                                                                roseRef.current.instanceMatrix.needsUpdate = true
                                                                                                                                                                                                                                                                                    roseRef.current.instanceColor.needsUpdate = true
                                                                                                                                                                                                                                                                                      }, [bushes, roses])

                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                            <>
                                                                                                                                                                                                                                                                                                  <instancedMesh ref={bushRef} args={[null, null, bushes.length]}>
                                                                                                                                                                                                                                                                                                          <sphereGeometry args={[1, 8, 6]} />
                                                                                                                                                                                                                                                                                                                  <meshStandardMaterial color="#3f8a4c" roughness={1} />
                                                                                                                                                                                                                                                                                                                        </instancedMesh>
                                                                                                                                                                                                                                                                                                                              <instancedMesh ref={roseRef} args={[null, null, roses.length]}>
                                                                                                                                                                                                                                                                                                                                      <sphereGeometry args={[0.16, 8, 6]} />
                                                                                                                                                                                                                                                                                                                                              <meshStandardMaterial color="#ffffff" roughness={0.6} />
                                                                                                                                                                                                                                                                                                                                                    </instancedMesh>
                                                                                                                                                                                                                                                                                                                                                        </>
                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                          export function Pedestal() {
                                                                                                                                                                                                                                                                                                                                                            const env = useRef()
                                                                                                                                                                                                                                                                                                                                                              useFrame((s) => {
                                                                                                                                                                                                                                                                                                                                                                  env.current.position.y = 1.32 + Math.sin(s.clock.elapsedTime * 1.5) * 0.04
                                                                                                                                                                                                                                                                                                                                                                      env.current.rotation.y = 0.25 + Math.sin(s.clock.elapsedTime * 0.8) * 0.15
                                                                                                                                                                                                                                                                                                                                                                        })
                                                                                                                                                                                                                                                                                                                                                                          return (
                                                                                                                                                                                                                                                                                                                                                                              <group position={[0, 0, -17]}>
                                                                                                                                                                                                                                                                                                                                                                                    <mesh position={[0, 0.575, 0]}>
                                                                                                                                                                                                                                                                                                                                                                                            <cylinderGeometry args={[0.45, 0.55, 1.15, 18]} />
                                                                                                                                                                                                                                                                                                                                                                                                    <meshStandardMaterial color={CREAM} roughness={0.5} />
                                                                                                                                                                                                                                                                                                                                                                                                          </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                <mesh position={[0, 1.18, 0]}>
                                                                                                                                                                                                                                                                                                                                                                                                                        <cylinderGeometry args={[0.62, 0.62, 0.06, 18]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                <meshStandardMaterial color={GOLD} metalness={0.4} roughness={0.35} emissive="#6b4e0a" />
                                                                                                                                                                                                                                                                                                                                                                                                                                      </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                            <group ref={env} position={[0, 1.32, 0]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                    <mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                              <boxGeometry args={[0.6, 0.04, 0.4]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <meshStandardMaterial color="#f7ecd7" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <mesh position={[0, 0.03, 0]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <sphereGeometry args={[0.07, 10, 10]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <meshStandardMaterial color="#a31228" emissive="#4a0510" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <sprite scale={[1.8, 1.8, 1]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <spriteMaterial map={getGlow()} transparent depthWrite={false} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </sprite>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </group>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </group>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          export function Lamps() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {[3, -4, -14].flatMap((z) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              [-1, 1].map((s) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <group key={`${s}${z}`} position={[s * 1.95, 0, z]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <mesh position={[0, 1.1, 0]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <cylinderGeometry args={[0.03, 0.04, 2.2, 6]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <meshStandardMaterial color={GOLD} metalness={0.4} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <mesh position={[0, 2.3, 0]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <sphereGeometry args={[0.16, 10, 10]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <meshBasicMaterial color="#fff3c8" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <sprite position={[0, 2.3, 0]} scale={[2.2, 2.2, 1]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <spriteMaterial map={getGlow()} transparent depthWrite={false} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </sprite>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </group>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    export function Petals() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const ref = useRef()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const data = useMemo(() => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const n = 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const p = new Float32Array(n * 3)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const v = new Float32Array(n)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (let i = 0; i < n; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              p[i * 3] = (Math.random() - 0.5) * 16
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    p[i * 3 + 1] = Math.random() * 7
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          p[i * 3 + 2] = 8 - Math.random() * 32
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                v[i] = 0.25 + Math.random() * 0.35
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return { p, v, n }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }, [])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            useFrame((s, dt) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const arr = data.p
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const t = s.clock.elapsedTime
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (let i = 0; i < data.n; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              arr[i * 3 + 1] -= data.v[i] * dt
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    arr[i * 3] += Math.sin(t + i) * 0.25 * dt
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (arr[i * 3 + 1] < 0) arr[i * 3 + 1] = 7
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ref.current.geometry.attributes.position.needsUpdate = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <points ref={ref}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <bufferGeometry>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <bufferAttribute attach="attributes-position" args={[data.p, 3]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </bufferGeometry>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <pointsMaterial color="#ff9bb5" size={0.1} transparent opacity={0.9} depthWrite={false} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </points>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }